  if (v === 2) { const a = ri(r, 4, sc + 6) + j % 3, b = ri(r, 3, sc + 4) + (j + 1) % 3; return { title: S('Obdĺžnik z obvodu', 'Rectangle from perimeter'), type: 'number', prompt: S(`Obdĺžnik má obvod ${2 * (a + b)} cm a jedna jeho strana má ${a} cm. Aký je jeho obsah?`, `A rectangle has a perimeter of ${2 * (a + b)} cm and one side of ${a} cm. What is its area?`), data: { answer: a * b, unit: 'cm²' },
    hints: [S('Obvod je 2 · (a + b). Koľko je a + b?', 'The perimeter is 2 · (a + b). What is a + b?'), S(`Poznáš a = ${a}. Aká je druhá strana?`, `You know a = ${a}. What is the other side?`)], explain: [S(`a + b = ${a + b} (polovica obvodu).`, `a + b = ${a + b} (half the perimeter).`), S(`Druhá strana: ${a + b} − ${a} = ${b} cm, obsah ${a} · ${b} = ${a * b} cm².`, `The other side: ${a + b} − ${a} = ${b} cm, area ${a} · ${b} = ${a * b} cm².`)] }; }
  if (v === 3) { const a = ri(r, 3, sc + 4) * 2, h2 = ri(r, 2, sc), t = ri(r, 1, 2); return { title: S('Obsah trojuholníka', 'Triangle area'), type: 'number', prompt: S(`Trojuholník má základňu ${a} cm a výšku na ňu ${h2 * 2 * t} cm. Aký je jeho obsah?`, `A triangle has a base of ${a} cm and a height to it of ${h2 * 2 * t} cm. What is its area?`), data: { answer: a * h2 * t, unit: 'cm²' },
    hints: [S('Trojuholník je polovica vhodného obdĺžnika.', 'A triangle is half of a suitable rectangle.'), S('Obsah = základňa · výška : 2.', 'Area = base · height : 2.')], explain: [S('Obsah trojuholníka = (základňa · výška) : 2.', 'Triangle area = (base · height) : 2.'), S(`(${a} · ${h2 * 2 * t}) : 2 = ${a * h2 * t} cm².`, `(${a} · ${h2 * 2 * t}) : 2 = ${a * h2 * t} cm².`)] }; }
  const a = ri(r, 8, sc + 12) + j, b = ri(r, 6, sc + 8), t = ri(r, 1, 3), outer = a * b, inner = (a - 2 * t) * (b - 2 * t); if (inner <= 0) return null;
  return { title: S('Rám obrazu', 'Picture frame'), type: 'number', prompt: S(`Obraz má vonkajšie rozmery ${a} cm × ${b} cm a rám široký ${t} cm po celom obvode. Aký je obsah samotného rámu (bez vnútornej plochy)?`, `A picture measures ${a} cm × ${b} cm outside, with a frame ${t} cm wide all around. What is the area of the frame itself (without the inner part)?`), data: { answer: outer - inner, unit: 'cm²' },
    hints: [S('Aké rozmery má vnútorná plocha?', 'What are the dimensions of the inner part?'), S(`Z každej strany ubudne ${t} cm – spolu ${2 * t} cm na jeden rozmer.`, `${t} cm goes from each side – ${2 * t} cm per dimension.`)], explain: [S(`Vnútro: (${a} − ${2 * t}) × (${b} − ${2 * t}) = ${a - 2 * t} × ${b - 2 * t} = ${inner} cm².`, `Inner part: (${a} − ${2 * t}) × (${b} − ${2 * t}) = ${a - 2 * t} × ${b - 2 * t} = ${inner} cm².`), S(`Rám = ${outer} − ${inner} = ${outer - inner} cm².`, `Frame = ${outer} − ${inner} = ${outer - inner} cm².`)] };
