function bridgeSolve(times) {
  const n = times.length, full = (1 << n) - 1, key = (m, s) => m * 2 + s, dist = new Map([[key(full, 0), 0]]), prev = new Map(), done = new Set();
  for (;;) {
    let bk = null, bd = Infinity; for (const [kk, d] of dist) if (!done.has(kk) && d < bd) { bd = d; bk = kk; } if (bk == null) return null; done.add(bk);
    const m = bk >> 1, s = bk & 1; if (m === 0 && s === 1) { const path = []; let cur = bk; while (prev.has(cur)) { const p = prev.get(cur); path.unshift(p); cur = p.from; } return { time: bd, path }; }
    const side = s === 0 ? range(n).filter(i => m >> i & 1) : range(n).filter(i => !(m >> i & 1));
    for (let a = 0; a < side.length; a++) for (let b = a; b < side.length; b++) {
      const who = a === b ? [side[a]] : [side[a], side[b]], t = Math.max(...who.map(i => times[i])); let nm = m; who.forEach(i => nm = s === 0 ? nm & ~(1 << i) : nm | (1 << i));
      const nk = key(nm, 1 - s), nd = bd + t; if (!done.has(nk) && (!dist.has(nk) || nd < dist.get(nk))) { dist.set(nk, nd); prev.set(nk, { from: bk, who, t, dir: s === 0 ? 'over' : 'back' }); }
    }
  }
}
