    while (q.length && !found) { const [x, y] = q.shift(); if (x === t || y === t) { found = [x, y]; break; } const nx = [[a, y, S('naplníme veľký džbán', '')], [x, b, null], [0, y, null], [x, 0, null], [Math.max(0, x - (b - y)), Math.min(b, y + x), null], [Math.min(a, x + y), Math.max(0, y - (a - x)), null]];
      nx.forEach(([p, qq]) => { const kk = key(p, qq); if (!prev.has(kk)) { prev.set(kk, [x, y]); q.push([p, qq]); } }); }
